// Function signature essence
int renameat2(int olddfd, const char *oldp,
              int newdfd, const char *newp,
              unsigned int flags);

// Standard constants (Requires headers like <fcntl.h>, <linux/fs.h>)
#define AT_FDCWD          (-100)
#define RENAME_NOREPLACE  1
#define RENAME_EXCHANGE   2

const char* file_a = "data.old";
const char* file_b = "data.new";

// Example 1: Atomically exchange file A and file B
int status = renameat2(AT_FDCWD, file_a,
                       AT_FDCWD, file_b,
                       RENAME_EXCHANGE);

// Example 2: Rename, but fail if target exists
status = renameat2(AT_FDCWD, "tmp.file",
                   AT_FDCWD, "final.file",
                   RENAME_NOREPLACE);
